export class VisitLine {
  static get type(): any;
  /**
   * @param {string} date
   * @param {string} description
   * @param {string} ownerFirstName
   * @param {string} ownerLastName
   */
  constructor(
    date: string,
    description: string,
    ownerFirstName: string,
    ownerLastName: string,
  );
  get instance(): any;
  /**
   * @returns {Promise<string>}
   */
  getOwnerFirstName(): Promise<string>;
  /**
   * @returns {Promise<string>}
   */
  getOwnerLastName(): Promise<string>;
  /**
   * @returns {Promise<string>}
   */
  getDate(): Promise<string>;
  /**
   * @returns {Promise<string>}
   */
  getDescription(): Promise<string>;
}
